// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {Ownable2Step, Ownable} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {LaunchToken} from "./LaunchToken.sol";
import {BondingCurvePoolV3} from "./BondingCurvePoolV3.sol";

/// @title LaunchpadFactoryV3
/// @notice Фабрика ETH-монет hood (перезапуск 09.2026): пулы BondingCurvePoolV3
///         со стартовым налогом против снайперов (99% → 0 за пять секунд,
///         создатель и до 32 названных им адресов освобождены). Комиссия 1%,
///         доля создателя задаётся initConfig (7000 = 70%), остаток — в казну
///         (сплиттер). Кривая: 1B сапплая, 800M на кривой, градация на 4 ETH (18.09.2026: было 6.5, у Pons 4.2)
///         в навсегда запертую позицию DEX.
contract LaunchpadFactoryV3 is Ownable2Step {
    // ------------------------------------------------------------- config
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000e18;
    uint256 public constant SALE_CAP     =   800_000_000e18;
    uint256 public constant VIRTUAL_ETH  = 1 ether; // -> graduates at 4 ETH (4 × virtual)

    /// @notice Потолок первой покупки создателя. Без него создатель забирал
    ///         сколь угодно большой мешок по стартовой цене и мог сливать его
    ///         в выкупы казны — то есть выкачивать общий призовой фонд.
    uint256 public constant CREATOR_MAX_FIRST_BUY = 0.08 ether; // ~2% кривой (4 ETH)

    /// @notice Лимиты метаданных: неограниченные строки ломают вёрстку
    ///         списков и раздувают кэш у каждого посетителя.
    uint256 public constant MAX_NAME_LEN = 64;
    uint256 public constant MAX_SYMBOL_LEN = 12;
    uint256 public constant MAX_URI_LEN = 200_000;

    /// @notice Задержка смены критичной конфигурации (мигратор/казна).
    ///         Владелец не может внезапно подменить мигратор и увести
    ///         ликвидность негradуировавших пулов — у всех есть 48 часов,
    ///         чтобы увидеть заявку и выйти.
    uint256 public constant CONFIG_DELAY = 48 hours;
    /// @notice Заявка действует столько после готовности; старую надо подать заново,
    ///         чтобы люди видели свежее предупреждение, а не применение месячной давности.
    uint256 public constant CONFIG_GRACE = 7 days;

    uint16 public feeBps = 100;              // 1% per trade
    uint16 public creatorFeeShareBps = 5000; // creator 50%; остальные 50% идут в
                                             // FeeSplitter (team 40% => 20% всего,
                                             // treasury 60% => 30% всего)

    address public treasury;   // FeeSplitter (team + BuybackTreasuryV2)
    address public migrator;
    address public votePower;  // fee => voting power hook

    // заявка на смену конфигурации (таймлок)
    struct PendingConfig {
        address treasury;
        address migrator;
        address votePower;
        uint16 feeBps;
        uint16 creatorFeeShareBps;
        uint256 readyAt;
    }
    PendingConfig public pendingConfig;

    // ------------------------------------------------------------- registry
    address[] public allTokens;
    mapping(address => address) public poolOf; // token => pool
    mapping(address => bool) public isPool;    // pool => registered (VotePower auth)
    /// @notice Пока владелец не вызвал initConfig, запуск монет закрыт — иначе
    ///         чужой createToken сразу после деплоя запирал бы первичную
    ///         настройку и первая монета площадки рождалась бы с дефолтами.
    bool public configured;

    event TokenCreated(
        address indexed token,
        address indexed pool,
        address indexed creator,
        string name,
        string symbol,
        string metadataURI
    );
    event ConfigUpdated(address treasury, address migrator, address votePower, uint16 feeBps, uint16 creatorFeeShareBps);
    event ConfigProposed(address treasury, address migrator, address votePower, uint16 feeBps, uint16 creatorFeeShareBps, uint256 readyAt);
    event ConfigCancelled();

    constructor(address treasury_, address migrator_) Ownable(msg.sender) {
        require(treasury_ != address(0) && migrator_ != address(0), "zero addr");
        treasury = treasury_;
        migrator = migrator_;
    }

    // ------------------------------------------------------------- launch

    /// @notice Запустить монету. Присланный ETH — первая покупка создателя
    ///         (в той же транзакции, без стартового налога: создатель освобождён).
    /// @param exempt до 32 адресов, освобождённых от стартового налога
    ///        (команда, партнёры); создатель освобождён всегда.
    function createToken(
        string calldata name,
        string calldata symbol,
        string calldata metadataURI,
        address creatorWallet,
        address[] calldata exempt
    ) external payable returns (address tokenAddr, address poolAddr) {
        require(bytes(name).length > 0 && bytes(name).length <= MAX_NAME_LEN, "name len");
        require(bytes(symbol).length > 0 && bytes(symbol).length <= MAX_SYMBOL_LEN, "symbol len");
        require(bytes(metadataURI).length <= MAX_URI_LEN, "uri len");
        require(msg.value <= CREATOR_MAX_FIRST_BUY, "first buy > cap");
        require(configured, "not configured");
        address creator_ = creatorWallet == address(0) ? msg.sender : creatorWallet;
        (tokenAddr, poolAddr) = _launch(name, symbol, metadataURI, creator_, exempt);
        emit TokenCreated(tokenAddr, poolAddr, creator_, name, symbol, metadataURI);
        if (msg.value > 0) {
            BondingCurvePoolV3(payable(poolAddr)).buy{value: msg.value}(0, creator_);
        }
    }

    /// @dev Деплой пары в отдельной функции — createToken держит минимальный
    ///      стек (три calldata-строки + массив упираются в stack-too-deep).
    function _launch(
        string calldata name,
        string calldata symbol,
        string calldata metadataURI,
        address creator_,
        address[] calldata exempt
    ) internal returns (address tokenAddr, address poolAddr) {
        BondingCurvePoolV3 pool = new BondingCurvePoolV3(
            _predictTokenAddress(),
            creator_,
            TOTAL_SUPPLY,
            SALE_CAP,
            VIRTUAL_ETH,
            feeBps,
            creatorFeeShareBps,
            exempt
        );
        LaunchToken token = new LaunchToken(name, symbol, metadataURI, address(pool), TOTAL_SUPPLY);
        require(address(token) == address(pool.token()), "addr mismatch");

        tokenAddr = address(token);
        poolAddr = address(pool);
        allTokens.push(tokenAddr);
        poolOf[tokenAddr] = poolAddr;
        isPool[poolAddr] = true;
    }

    /// @dev Address of the *next* contract this factory deploys with CREATE.
    function _predictTokenAddress() internal view returns (address) {
        uint256 nonce = _nonce() + 1;
        return _computeCreateAddress(address(this), nonce);
    }

    function _nonce() internal view returns (uint256 n) {
        return 1 + allTokens.length * 2;
    }

    function _computeCreateAddress(address deployer, uint256 nonce) internal pure returns (address) {
        bytes memory data;
        if (nonce == 0x00) {
            data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), deployer, bytes1(0x80));
        } else if (nonce <= 0x7f) {
            data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), deployer, uint8(nonce));
        } else if (nonce <= 0xff) {
            data = abi.encodePacked(bytes1(0xd7), bytes1(0x94), deployer, bytes1(0x81), uint8(nonce));
        } else if (nonce <= 0xffff) {
            data = abi.encodePacked(bytes1(0xd8), bytes1(0x94), deployer, bytes1(0x82), uint16(nonce));
        } else if (nonce <= 0xffffff) {
            data = abi.encodePacked(bytes1(0xd9), bytes1(0x94), deployer, bytes1(0x83), uint24(nonce));
        } else {
            data = abi.encodePacked(bytes1(0xda), bytes1(0x94), deployer, bytes1(0x84), uint32(nonce));
        }
        return address(uint160(uint256(keccak256(data))));
    }

    // ------------------------------------------------------------- admin

    /// @notice Шаг 1: заявить смену конфигурации. Вступит в силу через
    ///         CONFIG_DELAY — до этого все видят заявку в событии и могут выйти.
    function proposeConfig(
        address treasury_,
        address migrator_,
        address votePower_,
        uint16 feeBps_,
        uint16 creatorFeeShareBps_
    ) external onlyOwner {
        _checkConfig(treasury_, migrator_, votePower_, feeBps_, creatorFeeShareBps_);
        pendingConfig = PendingConfig({
            treasury: treasury_,
            migrator: migrator_,
            votePower: votePower_,
            feeBps: feeBps_,
            creatorFeeShareBps: creatorFeeShareBps_,
            readyAt: block.timestamp + CONFIG_DELAY
        });
        emit ConfigProposed(treasury_, migrator_, votePower_, feeBps_, creatorFeeShareBps_, block.timestamp + CONFIG_DELAY);
    }

    /// @notice Шаг 2: применить заявку после истечения таймлока.
    function applyConfig() external onlyOwner {
        PendingConfig memory p = pendingConfig;
        require(p.readyAt != 0, "no pending");
        require(block.timestamp >= p.readyAt, "timelock");
        require(block.timestamp <= p.readyAt + CONFIG_GRACE, "expired");
        treasury = p.treasury;
        migrator = p.migrator;
        votePower = p.votePower;
        feeBps = p.feeBps;
        creatorFeeShareBps = p.creatorFeeShareBps;
        delete pendingConfig;
        emit ConfigUpdated(p.treasury, p.migrator, p.votePower, p.feeBps, p.creatorFeeShareBps);
    }

    /// @notice Отозвать заявку (например, если передумали).
    function cancelConfig() external onlyOwner {
        delete pendingConfig;
        emit ConfigCancelled();
    }

    /// @dev Первичная настройка сразу после деплоя — один раз и без задержки,
    ///      пока в фабрике ещё нет ни одного токена (терять нечего).
    function initConfig(
        address treasury_,
        address migrator_,
        address votePower_,
        uint16 feeBps_,
        uint16 creatorFeeShareBps_
    ) external onlyOwner {
        require(allTokens.length == 0, "already launched");
        _checkConfig(treasury_, migrator_, votePower_, feeBps_, creatorFeeShareBps_);
        treasury = treasury_;
        migrator = migrator_;
        votePower = votePower_;
        feeBps = feeBps_;
        creatorFeeShareBps = creatorFeeShareBps_;
        configured = true;
        emit ConfigUpdated(treasury_, migrator_, votePower_, feeBps_, creatorFeeShareBps_);
    }

    /// @dev Общие проверки конфигурации. Адреса — только с кодом: пустой адрес
    ///      мигратора заморозил бы градацию, а хук без кода — все сделки
    ///      (проверка extcodesize у try/catch не ловится).
    function _checkConfig(
        address treasury_,
        address migrator_,
        address votePower_,
        uint16 feeBps_,
        uint16 creatorFeeShareBps_
    ) internal view {
        require(treasury_ != address(0) && migrator_ != address(0), "zero addr");
        require(migrator_.code.length > 0, "migrator: no code");
        require(votePower_ == address(0) || votePower_.code.length > 0, "votePower: no code");
        require(feeBps_ <= 500, "fee>5%");
        require(creatorFeeShareBps_ <= 10_000, "share>100%");
    }

    /// @dev Возврат сдачи от пула, если первая покупка упёрлась в кривую:
    ///      деньги принадлежат создателю токена, ему и уходят.
    receive() external payable {
        require(isPool[msg.sender], "only pools");
        address to = BondingCurvePoolV3(payable(msg.sender)).creator();
        (bool ok, ) = to.call{value: msg.value}("");
        require(ok, "refund failed");
    }

    // ------------------------------------------------------------- views

    function tokenCount() external view returns (uint256) {
        return allTokens.length;
    }

    function tokens(uint256 offset, uint256 limit) external view returns (address[] memory out) {
        uint256 n = allTokens.length;
        if (offset >= n) return new address[](0);
        uint256 end = offset + limit > n ? n : offset + limit;
        out = new address[](end - offset);
        for (uint256 i = offset; i < end; i++) {
            out[i - offset] = allTokens[i];
        }
    }
}

BondingCurvePoolV3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ILiquidityMigrator} from "./interfaces/ILiquidityMigrator.sol";
import {OpeningTax} from "./OpeningTax.sol";

interface IVotePowerHookV3 {
    function recordFee(address trader, uint256 fee) external;
}

/// @title BondingCurvePoolV3
/// @notice Та же constant-product кривая, что BondingCurvePoolV2, плюс
///         стартовый налог против снайперов (OpeningTax): первые пять секунд
///         после запуска покупка облагается налогом 99% → 0, только покупки,
///         создатель и названные им адреса освобождены. Налог попадает в тот же
///         котёл комиссий и делится по тем же долям (creatorFeeShareBps).
///
///         Порядок вычетов при покупке: сначала налог с полной суммы, потом
///         обычная комиссия с остатка, остаток — в кривую. В событии Buy поле
///         fee — всё, что ушло площадке (комиссия + налог); налог отдельно —
///         в событии OpeningTaxPaid.
contract BondingCurvePoolV3 is ReentrancyGuard, OpeningTax {
    using SafeERC20 for IERC20;

    // ---------------------------------------------------------- immutables
    IERC20  public immutable token;
    address public immutable factory;
    address public immutable creator;

    uint256 public immutable totalSupply;
    uint256 public immutable saleCap;
    uint256 public immutable virtualEth;
    uint16  public immutable feeBps;
    uint16  public immutable creatorFeeShareBps;

    // ------------------------------------------------------------- state
    uint256 public ethReserve;
    uint256 public tokensSold;
    bool    public graduated;
    bool    public migrated;

    uint256 public protocolFeesAccrued;
    uint256 public creatorFeesAccrued;
    /// @notice Сколько стартового налога собрано за жизнь кривой.
    uint256 public openingTaxPaid;

    /// @notice Потолок суммарных покупок создателя на этой кривой (~2% от 4 ETH).
    uint256 public constant CREATOR_BUY_CAP = 0.08 ether;
    uint256 public creatorSpent;

    // ------------------------------------------------------------- events
    event Buy(address indexed buyer, uint256 ethIn, uint256 tokensOut, uint256 fee);
    event Sell(address indexed seller, uint256 tokensIn, uint256 ethOut, uint256 fee);
    event Graduated(uint256 ethReserve, uint256 dexTokenReserve);
    event Migrated(address indexed migrator, uint256 ethAmount, uint256 tokenAmount);
    /// @notice Перенос на DEX в покупке-градации не прошёл — доделает migrate().
    event MigrationDeferred();
    event FeesClaimed(address indexed to, uint256 amount, bool isCreator);

    error TradingClosed();
    error CreatorCapExceeded();
    error SlippageExceeded();
    error ZeroAmount();
    error NotGraduated();
    error AlreadyMigrated();
    error NotAuthorized();

    constructor(
        address token_,
        address creator_,
        uint256 totalSupply_,
        uint256 saleCap_,
        uint256 virtualEth_,
        uint16  feeBps_,
        uint16  creatorFeeShareBps_,
        address[] memory exempt_
    ) OpeningTax(creator_, exempt_) {
        require(saleCap_ < totalSupply_, "cap>=supply");
        require(token_ != address(0) && creator_ != address(0), "zero addr");
        require(feeBps_ <= 500, "fee>5%");
        require(creatorFeeShareBps_ <= 10_000, "share>100%");
        factory = msg.sender;
        token = IERC20(token_);
        creator = creator_;
        totalSupply = totalSupply_;
        saleCap = saleCap_;
        virtualEth = virtualEth_;
        feeBps = feeBps_;
        creatorFeeShareBps = creatorFeeShareBps_;
    }

    // ------------------------------------------------------------- views

    function spotPrice() external view returns (uint256) {
        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        return (x * 1e18) / y;
    }

    /// @notice Оценка покупки без стартового налога (после пятой секунды —
    ///         точная). Для первых секунд — quoteBuyFor с адресом покупателя.
    function quoteBuy(uint256 ethInGross) public view returns (uint256 tokensOut) {
        return _quote(ethInGross, 0);
    }

    /// @notice Оценка покупки для конкретного получателя с учётом налога.
    function quoteBuyFor(address recipient, uint256 ethInGross) external view returns (uint256 tokensOut) {
        return _quote(ethInGross, _openingTaxBps(recipient, recipient));
    }

    function quoteSell(uint256 tokensIn) public view returns (uint256 ethOutGross) {
        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        ethOutGross = (x * tokensIn) / (y + tokensIn);
    }

    function _quote(uint256 gross, uint16 taxBps) internal view returns (uint256 tokensOut) {
        uint256 afterTax = gross - (gross * taxBps) / 10_000;
        uint256 ethIn = afterTax - (afterTax * feeBps) / 10_000;
        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        tokensOut = (y * ethIn) / (x + ethIn);
    }

    // ------------------------------------------------------------- trading

    function buy(uint256 minTokensOut, address recipient)
        external
        payable
        nonReentrant
        returns (uint256 tokensOut)
    {
        if (graduated) revert TradingClosed();
        if (msg.value == 0) revert ZeroAmount();

        // Кап создателя — суммарно за жизнь кривой, обходу через прямой вызов
        // пула не поддаётся.
        if (recipient == creator || msg.sender == creator) {
            creatorSpent += msg.value;
            if (creatorSpent > CREATOR_BUY_CAP) revert CreatorCapExceeded();
        }

        // Стартовый налог — с полной суммы, обычная комиссия — с остатка.
        uint16 taxBps = _openingTaxBps(msg.sender, recipient);
        uint256 tax = (msg.value * taxBps) / 10_000;
        uint256 fee = ((msg.value - tax) * feeBps) / 10_000;
        uint256 ethIn = msg.value - tax - fee;

        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        tokensOut = (y * ethIn) / (x + ethIn);

        uint256 refund;
        uint256 remaining = saleCap - tokensSold;
        if (tokensOut >= remaining) {
            tokensOut = remaining;
            uint256 ethNeeded = (x * tokensOut + (y - tokensOut) - 1) / (y - tokensOut);
            if (ethNeeded > ethIn) ethNeeded = ethIn;
            // сколько нужно внести, чтобы после налога и комиссии осталось ethNeeded
            uint256 keep = (10_000 - uint256(taxBps)) * (10_000 - uint256(feeBps)); // из 1e8
            uint256 grossNeeded = (ethNeeded * 100_000_000 + keep - 1) / keep;
            if (grossNeeded > msg.value) grossNeeded = msg.value;
            refund = msg.value - grossNeeded;
            tax = (grossNeeded * taxBps) / 10_000;
            fee = grossNeeded - tax - ethNeeded; // остаток округления — в комиссию
            ethIn = ethNeeded;
        }

        if (tokensOut < minTokensOut) revert SlippageExceeded();
        if (tokensOut == 0) revert ZeroAmount();

        // effects
        ethReserve += ethIn;
        tokensSold += tokensOut;
        _accrueFees(fee + tax);
        if (tax > 0) {
            openingTaxPaid += tax;
            emit OpeningTaxPaid(recipient, tax, taxBps);
        }

        bool willGraduate = tokensSold >= saleCap;
        if (willGraduate) {
            graduated = true;
        }

        // interactions
        _reportFee(msg.sender, fee + tax);
        token.safeTransfer(recipient, tokensOut);
        if (refund > 0) _sendEth(msg.sender, refund);

        emit Buy(recipient, ethIn, tokensOut, fee + tax);
        if (willGraduate) {
            emit Graduated(ethReserve, totalSupply - saleCap);
            // Как у Pons: ликвидность уезжает на DEX в той же покупке, что
            // добила кривую, — без паузы. Если перенос сорвался (цена в пуле
            // Uniswap сбита сильнее допуска мигратора), покупку не ломаем:
            // деньги остаются на кривой, migrate() дозовёт бот или кто угодно.
            try this.migrateSelf() {} catch {
                emit MigrationDeferred();
            }
        }
    }

    function sell(uint256 tokensIn, uint256 minEthOut)
        external
        nonReentrant
        returns (uint256 ethToUser)
    {
        if (graduated) revert TradingClosed();
        if (tokensIn == 0) revert ZeroAmount();

        uint256 x = virtualEth + ethReserve;
        uint256 y = totalSupply - tokensSold;
        uint256 ethOutGross = (x * tokensIn) / (y + tokensIn);
        if (ethOutGross > ethReserve) ethOutGross = ethReserve;

        uint256 fee = (ethOutGross * feeBps) / 10_000;
        ethToUser = ethOutGross - fee;
        if (ethToUser < minEthOut) revert SlippageExceeded();

        // effects
        ethReserve -= ethOutGross;
        tokensSold -= tokensIn;
        _accrueFees(fee);

        // interactions
        _reportFee(msg.sender, fee);
        token.safeTransferFrom(msg.sender, address(this), tokensIn);
        _sendEth(msg.sender, ethToUser);

        emit Sell(msg.sender, tokensIn, ethToUser, fee);
    }

    // ------------------------------------------------------------- migration

    function migrate() external nonReentrant {
        _migrate();
    }

    /// @dev Вызов из buy() той же транзакции (см. там). Только сам контракт;
    ///      замок nonReentrant уже держит buy(), поэтому здесь его нет.
    function migrateSelf() external {
        if (msg.sender != address(this)) revert NotAuthorized();
        _migrate();
    }

    function _migrate() internal {
        if (!graduated) revert NotGraduated();
        if (migrated) revert AlreadyMigrated();
        migrated = true;

        address migrator = IFactoryConfigV3(factory).migrator();
        uint256 tokenAmount = totalSupply - saleCap;
        uint256 ethAmount = ethReserve;
        ethReserve = 0;

        token.safeTransfer(migrator, tokenAmount);
        ILiquidityMigrator(migrator).migrate{value: ethAmount}(address(token), tokenAmount);

        emit Migrated(migrator, ethAmount, tokenAmount);
    }

    // ------------------------------------------------------------- fees

    function claimCreatorFees(address to) external nonReentrant {
        if (msg.sender != creator) revert NotAuthorized();
        require(to != address(0), "zero recipient"); // иначе комиссии сгорают
        uint256 amount = creatorFeesAccrued;
        creatorFeesAccrued = 0;
        _sendEth(to, amount);
        emit FeesClaimed(to, amount, true);
    }

    function claimProtocolFees() external nonReentrant {
        address treasury = IFactoryConfigV3(factory).treasury();
        uint256 amount = protocolFeesAccrued;
        protocolFeesAccrued = 0;
        _sendEth(treasury, amount);
        emit FeesClaimed(treasury, amount, false);
    }

    // ------------------------------------------------------------- internal

    function _accrueFees(uint256 fee) internal {
        if (fee == 0) return;
        uint256 creatorCut = (fee * creatorFeeShareBps) / 10_000;
        creatorFeesAccrued += creatorCut;
        protocolFeesAccrued += fee - creatorCut;
    }

    /// @dev Хук голосования: никогда не блокирует сделку (см. V2).
    function _reportFee(address trader, uint256 fee) internal {
        address hook = IFactoryConfigV3(factory).votePower();
        if (hook == address(0) || fee == 0 || hook.code.length == 0) return;
        try IVotePowerHookV3(hook).recordFee{gas: 150_000}(trader, fee) {} catch {}
    }

    function _sendEth(address to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH send failed");
    }
}

interface IFactoryConfigV3 {
    function migrator() external view returns (address);
    function treasury() external view returns (address);
    function votePower() external view returns (address);
}

OpeningTax.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title OpeningTax — стартовый налог против снайперов (как у Pons)
/// @notice Первые секунды после запуска монеты покупка облагается налогом,
///         который стартует с 99% и за пять секунд падает до нуля. Снайпер-бот,
///         который бьёт в первый блок, отдаёт почти всё в комиссию; человек,
///         который открывает страницу через минуту, налога не видит вообще.
///
///         Правила:
///           - только покупки; продажи не облагаются никогда;
///           - создатель монеты освобождён (его покупка в той же транзакции,
///             что и создание, идёт без налога), плюс до 32 адресов, которые
///             создатель называет при запуске — команда, партнёры, свои кошельки;
///           - налог не сжигается: он попадает в общий котёл комиссий и делится
///             как обычная комиссия сделки (создатель / арена / выкуп / команда);
///           - секунды считаются по времени блока: покупки внутри одной
///             секунды платят одинаково.
///
///         Шкала (доля от суммы покупки): 0-я секунда 99%, 1-я 25%, 2-я 3%,
///         3-я 0,4%, 4-я 0,05%, с 5-й — ноль. Таблица вместо экспоненты:
///         те же числа, что заявляет Pons, и ни одного дробного вычисления.
abstract contract OpeningTax {
    /// @notice Момент запуска (время блока создания пула).
    uint256 public immutable launchedAt;
    // Окно налога — 5 секунд (шкала ниже); отдельной константы нет, чтобы
    // не раздувать байткод фабрики, в которую пул встроен целиком.
    /// @notice Сколько адресов можно освободить от налога сверх создателя.
    uint256 public constant MAX_EXEMPT = 32;

    /// @notice Освобождён от стартового налога.
    mapping(address => bool) public taxExempt;
    address[] private _exempt;

    event OpeningTaxPaid(address indexed buyer, uint256 amount, uint16 bps);
    event TaxExempted(address indexed account);

    error TooManyExempt();

    constructor(address creator_, address[] memory exempt_) {
        launchedAt = block.timestamp;
        if (exempt_.length > MAX_EXEMPT) revert TooManyExempt();
        _setExempt(creator_);
        for (uint256 i = 0; i < exempt_.length; i++) _setExempt(exempt_[i]);
    }

    // ------------------------------------------------------------- views

    /// @notice Налог прямо сейчас, bps от суммы покупки.
    function openingTaxBps() public view returns (uint16) {
        return openingTaxBpsAt(block.timestamp);
    }

    /// @notice Налог в момент `ts`, bps. Ноль с пятой секунды.
    function openingTaxBpsAt(uint256 ts) public view returns (uint16) {
        if (ts < launchedAt) return 9_900;
        uint256 s = ts - launchedAt;
        if (s == 0) return 9_900;
        if (s == 1) return 2_500;
        if (s == 2) return 300;
        if (s == 3) return 40;
        if (s == 4) return 5;
        return 0;
    }

    /// @notice Освобождённые адреса (создатель — первым).
    function exemptList() external view returns (address[] memory) {
        return _exempt;
    }

    // ------------------------------------------------------------- internal

    /// @dev Ставка налога для этой покупки, bps: ноль, если окно закрыто или
    ///      платит / получает освобождённый адрес (для покупки через зап или
    ///      фабрику важен получатель, не отправитель). Саму сумму считает пул —
    ///      у него есть точные числа после всех округлений.
    function _openingTaxBps(address payer, address recipient) internal view returns (uint16) {
        uint16 bps = openingTaxBps();
        if (bps == 0) return 0;
        if (taxExempt[recipient] || taxExempt[payer]) return 0;
        return bps;
    }

    function _setExempt(address a) private {
        if (a == address(0) || taxExempt[a]) return;
        taxExempt[a] = true;
        _exempt.push(a);
        emit TaxExempted(a);
    }
}

interfaces/ILiquidityMigrator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @notice Pluggable liquidity migrator. When a token graduates from the
///         bonding curve, the pool sends the DEX reserve (tokens + ETH)
///         here and the migrator creates a permanently locked DEX position.
interface ILiquidityMigrator {
    /// @param token       the graduated token (already transferred to the migrator)
    /// @param tokenAmount amount of tokens transferred for liquidity
    /// @dev   ETH for liquidity is sent as msg.value.
    function migrate(address token, uint256 tokenAmount) external payable;
}

